INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'clerk', 'n.', '/klɑːk/', '职员;文书;店员', 'The clerk did not believe a poor-looking man could be rich.', '店员不相信一个衣着寒酸的人会有钱。', 'The Value of Money', 1, 0, 'senior', 'wordlist', 'required3', 'U5', 'a shop clerk', '美音 /klɜːrk/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'consulate', 'n.', '/ˈkɒnsjələt/', '领事馆', 'Henry went to the American consulate to ask for help, but got none.', '亨利去美国领事馆求助,却没得到任何帮助。', 'The Value of Money', 2, 0, 'senior', 'wordlist', 'required3', 'U5', 'go to the consulate', '美音 /ˈkɑːnsələt/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'dare', 'v.', '/deə(r)/', '胆敢;敢于', 'I dare not buy all these clothes without any money.', '我身无分文,不敢买下这些衣服。', 'The Value of Money', 3, 0, 'senior', 'wordlist', 'required3', 'U5', 'dare to do sth', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'downstairs', 'adv.', '/ˌdaʊnˈsteəz/', '顺楼梯而下;在楼下;往楼下', 'The clerk told him the cheaper suits were downstairs.', '店员告诉他便宜的西装在楼下。', 'The Value of Money', 4, 0, 'senior', 'wordlist', 'required3', 'U5', 'go downstairs', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'duty', 'n.', '/ˈdjuːti/', '责任;义务;职责;值班', 'Henry felt it was his duty to attend the ambassador''s party.', '亨利觉得参加大使的聚会是他的责任。', 'The Value of Money', 5, 0, 'senior', 'wordlist', 'required3', 'U5', 'sense of duty', '美音 /ˈduːti/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'on duty', 'phr.', '/ɒn ˈdjuːti/', '值班;值勤', 'He said he would be on duty at the library this afternoon.', '他说今天下午他要在图书馆值班。', 'The Value of Money', 6, 0, 'senior', 'wordlist', 'required3', 'U5', 'be on duty', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'element', 'n.', '/ˈelɪmənt/', '要素;基本部分', 'A good scene must include every element of a play.', '一个好的场景必须包含戏剧的每一个要素。', 'The Value of Money', 7, 0, 'senior', 'wordlist', 'required3', 'U5', 'an element of a play', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'eventually', 'adv.', '/ɪˈventʃuəli/', '最后;终于', 'Eventually the shop owner realised the bank note was real.', '店主最终意识到那张钞票是真的。', 'The Value of Money', 8, 0, 'senior', 'wordlist', 'required3', 'U5', 'eventually succeed', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'extent', 'n.', '/ɪkˈstent/', '程度;限度;大小;范围', 'The consulate could help him to some extent, but not fully.', '领事馆能在一定程度上帮他,但帮不了太多。', 'The Value of Money', 9, 0, 'senior', 'wordlist', 'required3', 'U5', 'to some extent', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'external', 'adj.', '/ɪkˈstɜːnl/', '外部的;外面的;外界的;外来的', 'We should not judge people by their external appearance.', '我们不应以外表来评判别人。', 'The Value of Money', 10, 0, 'senior', 'wordlist', 'required3', 'U5', 'external appearance', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'frown', 'n./v.', '/fraʊn/', '皱眉', 'The clerk looked at Henry''s worn coat with a frown.', '店员皱着眉头看亨利那件破旧的外套。', 'The Value of Money', 11, 0, 'senior', 'wordlist', 'required3', 'U5', 'with a frown', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'hesitate', 'v.', '/ˈhezɪteɪt/', '犹豫;迟疑;顾虑', 'The owner thought Henry was hesitating to pay the bill.', '店主以为亨利在迟疑着不肯付账。', 'The Value of Money', 12, 0, 'senior', 'wordlist', 'required3', 'U5', 'hesitate to pay', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'hug', 'v./n.', '/hʌɡ/', '拥抱;抱紧', 'I was so happy at the news that I gave him a hug.', '我听到这消息太高兴了,给了他一个拥抱。', 'The Value of Money', 13, 0, 'senior', 'wordlist', 'required3', 'U5', 'give sb a hug', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'ignore', 'v.', '/ɪɡˈnɔː(r)/', '忽视;对……不予理会', 'While listening, don''t ignore the speaker''s tone and feelings.', '听的时候,别忽视说话人的语气和情绪。', 'The Value of Money', 14, 0, 'senior', 'wordlist', 'required3', 'U5', 'ignore the tone', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'in case', 'phr.', '/ɪn keɪs/', '以防;以防万一', 'Keep some cash in case you lose your money on a trip.', '随身带些现金,以防旅途中弄丢了钱。', 'The Value of Money', 15, 0, 'senior', 'wordlist', 'required3', 'U5', 'in case it happens', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'in return', 'phr.', '/ɪn rɪˈtɜːn/', '作为回报;作为回应', 'She helped the stranger and expected nothing in return.', '她帮助了那个陌生人,不求任何回报。', 'The Value of Money', 16, 0, 'senior', 'wordlist', 'required3', 'U5', 'expect nothing in return', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'indeed', 'adv.', '/ɪnˈdiːd/', '其实;实际上;确实', 'You will need many suits, yes, indeed you will.', '你会需要很多套西装,真的,你确实会。', 'The Value of Money', 17, 0, 'senior', 'wordlist', 'required3', 'U5', 'yes indeed', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'indicate', 'v.', '/ˈɪndɪkeɪt/', '表明;显示;暗示', 'The implied meaning often indicates people''s true feelings.', '言外之意往往暗示着人们真实的情感。', 'The Value of Money', 18, 0, 'senior', 'wordlist', 'required3', 'U5', 'indicate a feeling', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'intention', 'n.', '/ɪnˈtenʃn/', '打算;计划;意图;目的', 'Henry had no intention of taking the brothers'' charity.', '亨利无意接受两兄弟的施舍。', 'The Value of Money', 19, 0, 'senior', 'wordlist', 'required3', 'U5', 'have no intention', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'judge', 'v./n.', '/dʒʌdʒ/', '评价;评判;判断;法官;裁判', 'You shouldn''t judge people by the clothes they wear.', '你不应以衣着来评判别人。', 'The Value of Money', 20, 0, 'senior', 'wordlist', 'required3', 'U5', 'judge people', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'loan', 'n.', '/ləʊn/', '贷款;借款', 'She had spent all her savings and taken out a large loan.', '她花光了所有积蓄,还借了一大笔贷款。', 'The Value of Money', 21, 0, 'senior', 'wordlist', 'required3', 'U5', 'take out a loan', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'take out a loan', 'phr.', '/teɪk aʊt ə ləʊn/', '取得贷款', 'He had to take out a loan to pay for his daughter''s care.', '他不得不贷款来支付女儿的治疗费用。', 'The Value of Money', 22, 0, 'senior', 'wordlist', 'required3', 'U5', 'take out a loan', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'maintain', 'v.', '/meɪnˈteɪn/', '维持;保持;维修;保养', 'Henry wanted to maintain a good relationship with the ambassador.', '亨利想和大使保持良好的关系。', 'The Value of Money', 23, 0, 'senior', 'wordlist', 'required3', 'U5', 'maintain a relationship', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'manner', 'n.', '/ˈmænə(r)/', '举止;行为方式;方法;[pl.]礼貌', 'The first clerk spoke to Henry in a rude manner.', '第一个店员用粗鲁的态度对亨利说话。', 'The Value of Money', 24, 0, 'senior', 'wordlist', 'required3', 'U5', 'in a rude manner', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'mining', 'n.', '/ˈmaɪnɪŋ/', '采矿;采矿业', 'Back in America, Henry had worked for a mining company.', '在美国时,亨利曾在一家采矿公司工作。', 'The Value of Money', 25, 0, 'senior', 'wordlist', 'required3', 'U5', 'a mining company', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'musical', 'n./adj.', '/ˈmjuːzɪkl/', '音乐剧;音乐的', 'Philip bought two tickets to watch a musical with his girlfriend.', '菲利普买了两张票要和女友去看音乐剧。', 'The Value of Money', 26, 0, 'senior', 'wordlist', 'required3', 'U5', 'watch a musical', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'narration', 'n.', '/nəˈreɪʃn/', '叙述;讲述;解说', 'The narration tells the audience what is happening in the play.', '解说告诉观众剧中正在发生什么。', 'The Value of Money', 27, 0, 'senior', 'wordlist', 'required3', 'U5', 'the narration of a play', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'narrator', 'n.', '/nəˈreɪtə(r)/', '(书、戏剧、电影中的)叙述者;讲述者', 'The narrator explains how the two brothers made their bet.', '叙述者解释了两兄弟是如何打赌的。', 'The Value of Money', 28, 0, 'senior', 'wordlist', 'required3', 'U5', 'the narrator says', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'normal', 'adj./n.', '/ˈnɔːml/', '正常的;一般的;常态', 'The owner said it was quite normal for a busy man to be moving.', '店主说一个大忙人正在搬家是很正常的。', 'The Value of Money', 29, 0, 'senior', 'wordlist', 'required3', 'U5', 'quite normal', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'nowhere', 'adv.', '/ˈnəʊweə(r)/', '无处;哪里都不', 'Henry was stuck in London with nowhere to stay.', '亨利困在伦敦,无处落脚。', 'The Value of Money', 30, 0, 'senior', 'wordlist', 'required3', 'U5', 'with nowhere to stay', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'obligation', 'n.', '/ˌɒblɪˈɡeɪʃn/', '义务;职责;责任', 'She felt a moral obligation to return the money she had found.', '她觉得有道义上的责任把捡到的钱还回去。', 'The Value of Money', 31, 0, 'senior', 'wordlist', 'required3', 'U5', 'a moral obligation', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'odd', 'adj.', '/ɒd/', '奇怪的;怪异的;反常的', 'Henry felt it was odd that he could not open the letter at once.', '亨利觉得不能马上拆信这件事很奇怪。', 'The Value of Money', 32, 0, 'senior', 'wordlist', 'required3', 'U5', 'feel odd', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'opera', 'n.', '/ˈɒprə/', '歌剧', 'He bought tickets for an opera at the weekend.', '他买了周末去看歌剧的票。', 'The Value of Money', 33, 0, 'senior', 'wordlist', 'required3', 'U5', 'go to the opera', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'option', 'n.', '/ˈɒpʃn/', '可选择的事物;选择;选择权', 'The shop offered Henry a wide range of options to choose from.', '店里给亨利提供了一大堆可供挑选的款式。', 'The Value of Money', 34, 0, 'senior', 'wordlist', 'required3', 'U5', 'a range of options', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'ought to', 'modal v.', '/ˈɔːt tə/', '应该;应当', 'It is getting late, so I ought to be on my way now.', '时间不早了,我该上路了。', 'The Value of Money', 35, 0, 'senior', 'wordlist', 'required3', 'U5', 'ought to go', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'patience', 'n.', '/ˈpeɪʃns/', '耐心;忍耐力;毅力', 'Have patience, and you will soon learn the whole story.', '耐心一点,你很快就会知道整件事的来龙去脉。', 'The Value of Money', 36, 0, 'senior', 'wordlist', 'required3', 'U5', 'have patience', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'permit', 'v.', '/pəˈmɪt/', '允许;准许', 'She kindly permitted the poor traveller to sit beside her.', '她好心地允许这个穷旅客坐在她身边。', 'The Value of Money', 37, 0, 'senior', 'wordlist', 'required3', 'U5', 'permit sb to do', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'permission', 'n.', '/pəˈmɪʃn/', '准许;许可;批准', '"I''d love to sit down, with your permission," said Henry.', '亨利说:“若您允许,我很乐意坐下。”', 'The Value of Money', 38, 0, 'senior', 'wordlist', 'required3', 'U5', 'with your permission', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'plot', 'n.', '/plɒt/', '故事情节;布局;阴谋', 'A good play needs a clear and exciting plot.', '一部好戏需要清晰而扣人心弦的情节。', 'The Value of Money', 39, 0, 'senior', 'wordlist', 'required3', 'U5', 'an exciting plot', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'postpone', 'v.', '/pəˈspəʊn/', '延迟;延期;延缓', 'Henry had to postpone opening the letter until two o''clock.', '亨利只得把拆信推迟到两点钟。', 'The Value of Money', 40, 0, 'senior', 'wordlist', 'required3', 'U5', 'postpone opening it', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'pursue', 'v.', '/pəˈsjuː/', '追求;致力于', 'Lily decided to settle in New York and pursue her dream of acting.', '莉莉决定在纽约定居,追求她的演员梦。', 'The Value of Money', 41, 0, 'senior', 'wordlist', 'required3', 'U5', 'pursue a dream', '美音 /pərˈsuː/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'sail', 'v.', '/seɪl/', '(船)航行;(人)乘船航行', 'Henry was sailing alone when a strong wind carried him out to sea.', '亨利独自航行时,一阵大风把他刮向了大海。', 'The Value of Money', 42, 0, 'senior', 'wordlist', 'required3', 'U5', 'sail out to sea', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'saying', 'n.', '/ˈseɪɪŋ/', '谚语;格言;警句', 'There is a saying that money is a good servant but a bad master.', '有句谚语说,金钱是好仆人,却是坏主人。', 'The Value of Money', 43, 0, 'senior', 'wordlist', 'required3', 'U5', 'an old saying', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'scene', 'n.', '/siːn/', '(戏剧的)场;现场;场面', 'The students were asked to write a new scene for the play.', '学生们被要求为这部剧写一个新场景。', 'The Value of Money', 44, 0, 'senior', 'wordlist', 'required3', 'U5', 'write a scene', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'servant', 'n.', '/ˈsɜːvənt/', '仆人;用人', 'Money is a good servant and a bad master.', '金钱是好仆人,也是坏主人。', 'The Value of Money', 45, 0, 'senior', 'wordlist', 'required3', 'U5', 'a good servant', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'sort', 'n.', '/sɔːt/', '种类;类别;品种', 'Henry hoped the brothers could offer him some sort of work.', '亨利希望两兄弟能给他某种工作。', 'The Value of Money', 46, 0, 'senior', 'wordlist', 'required3', 'U5', 'this sort of work', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'spot', 'v./n.', '/spɒt/', '看见;注意到;发现;地点;斑点', 'The next morning he was spotted by a passing ship.', '第二天早上他被一艘过往的船发现了。', 'The Value of Money', 47, 0, 'senior', 'wordlist', 'required3', 'U5', 'be spotted by', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'stair', 'n.', '/steə(r)/', '楼梯;梯级', 'He went down some stairs to look for a cheaper suit.', '他走下几级楼梯去找便宜些的西装。', 'The Value of Money', 48, 0, 'senior', 'wordlist', 'required3', 'U5', 'go down the stairs', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'tailor', 'n./v.', '/ˈteɪlə(r)/', '裁缝;专门制作;定做', 'Henry saw a sign for a tailor''s shop and went in for a coat.', '亨利看到一家裁缝店的招牌,便进去买外套。', 'The Value of Money', 49, 0, 'senior', 'wordlist', 'required3', 'U5', 'the tailor''s shop', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'to be honest', 'phr.', '/tə bi ˈɒnɪst/', '说实话;坦率地说', 'To be honest, I have no money at all right now.', '说实话,我现在身无分文。', 'The Value of Money', 50, 0, 'senior', 'wordlist', 'required3', 'U5', 'to be honest', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'upper', 'adj.', '/ˈʌpə(r)/', '上面的;上层的;靠上部的', 'The ambassador invited Henry to an upper-class party.', '大使邀请亨利参加一场上流社会的聚会。', 'The Value of Money', 51, 0, 'senior', 'wordlist', 'required3', 'U5', 'the upper class', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'willing', 'adj.', '/ˈwɪlɪŋ/', '愿意;乐意', 'Why was the owner willing to wait so long to get paid?', '店主为什么愿意等这么久才收钱呢?', 'The Value of Money', 52, 0, 'senior', 'wordlist', 'required3', 'U5', 'be willing to do', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('r3u5.01', '①表推测可能性(must / can''t / may / might / could)', 'A2', 10, '必修三 U5 — 对现在或一般情况作推测:证据充分的肯定推测用 must("一定");证据不足的可能推测用 may/might/could("也许");否定推测("不可能")用 can''t。强弱看语境给的证据。', 1, 'required3', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('r3u5.02', '②表义务/建议/必要(should / ought to / must / have to / had better / need)', 'A2', 10, '必修三 U5 — 表应该/最好/必须做某事:建议或本分用 should/ought to;强烈必要或规定用 must/have to;给当下具体劝告用 had better;表必要用 need。', 2, 'required3', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('r3u5.03', '③表能力/请求/意愿 + would 表过去将来或过去习惯(can/could/will/would)', 'A2', 10, '必修三 U5 — 表能力用 can/could;客气请求用 could/would;表意愿用 will/would;转述"过去的将来"(He said he would…)及"过去反复习惯"(she would sit for hours)用 would。', 3, 'required3', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.01'), '"Henry has his own boat and once worked for a mining company, so he ____ be completely poor — yet he is."', 'can''t', 'must', 'should', 'would', 'A', '前提给出他有船有工作,推断"不可能完全是穷光蛋"——否定推测用 can''t。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.01'), '"The owner stared at the note. ''This ____ be the million-pound note I read about in the papers last week!''"', 'can''t', 'must', 'need', 'ought', 'B', '有报纸为证、惊讶认出,强肯定推测"一定是"——must。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.01'), '"Nobody answered the door, so the brothers ____ be out for the afternoon."', 'can''t', 'would', 'might', 'had better', 'C', '只凭没人应门,证据不足的可能推测"也许出门了"——might。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.01'), '"He is wearing a worn coat and has no small change, so he ____ be a very rich man," thought the clerk.', 'must', 'should', 'need', 'can''t', 'D', '破外套、没零钱,推断"不可能是富翁"——否定推测 can''t。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.01'), '"The light is still on upstairs, so someone ____ still be working in the office."', 'must', 'can''t', 'need', 'would', 'A', '灯还亮着是有力证据,"一定还有人在"——must。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.01'), '"I''m not sure where Henry went after the party; he ____ have gone back to his hotel."', 'can''t', 'may', 'should', 'ought to', 'B', '"不确定"表明证据不足,弱推测"也许回酒店了"——may。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.01'), '"She returned every cent and refused a reward, so she ____ be a truly honest person."', 'can''t', 'had better', 'must', 'would', 'C', '拒赏还钱是充分证据,"一定是诚实的人"——must。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.01'), '"The bag was empty when she opened it, so the money ____ be inside it now."', 'must', 'need', 'should', 'can''t', 'D', '袋子是空的,推断"钱不可能在里面"——can''t。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.01'), '"The owner isn''t certain, but the strange customer ____ be that famous American everyone is talking about."', 'could', 'can''t', 'must', 'ought to', 'A', '"不确定"提示弱推测"可能是"——could。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.01'), '"He hasn''t eaten since this morning, so he ____ be very hungry by now."', 'can''t', 'must', 'need', 'would', 'B', '一整天没吃,"现在一定很饿"——强推测 must。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.01'), '"Perhaps the brothers were joking, or perhaps not; the whole thing ____ still be some kind of trick."', 'must', 'can''t', 'might', 'should', 'C', '"perhaps"显示不确定,弱推测"也许仍是个把戏"——might。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.01'), '"A poor sailor ____ possibly own a million-pound note," the waiter thought when he first saw Henry.', 'must', 'should', 'would', 'can''t', 'D', '侍者认为穷水手"不可能拥有百万钞票"——否定推测 can''t。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.01'), '"His face turned pale and his hands shook, so the news ____ have shocked him deeply."', 'must', 'can''t', 'need', 'ought to', 'A', '脸白手抖是有力证据,"消息一定深深震惊了他"——must。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.01'), '"I''m not sure, but Lily ____ become a famous actress one day if she keeps trying."', 'can''t', 'may', 'must', 'had better', 'B', '"不确定"表明只是可能性,"也许有一天会成名"——may。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.01'), '"There is mud all over his shoes, so he ____ have walked here through the fields."', 'can''t', 'need', 'must', 'would', 'C', '满鞋是泥的实证,"一定是穿过田野走来的"——must。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.01'), '"The shop was locked and dark all day, so they ____ have been open this morning."', 'must', 'should', 'may', 'can''t', 'D', '整天锁着又黑,"今早不可能开过门"——can''t。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.01'), '"Who knows? The mysterious gift ____ turn out to be a fortune or just an old joke."', 'might', 'must', 'can''t', 'ought to', 'A', '"谁知道呢"显示不确定,弱推测"也许会是"——might。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.01'), '"She earns a small wage and lives simply, so she ____ be the wealthy widow you imagine."', 'must', 'can''t', 'need', 'would', 'B', '工资微薄、生活简朴,"不可能是想象中的富婆"——can''t。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.01'), '"The lights, the music and the laughter show the party ____ be in full swing."', 'can''t', 'should', 'must', 'may', 'C', '灯光、音乐、笑声都是证据,"派对一定正热闹"——must。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.01'), '"I have no idea where he is; he ____ be at the consulate, but I really can''t say."', 'must', 'can''t', 'had better', 'may', 'D', '"完全不知道"显示证据不足,弱推测"也许在领事馆"——may。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.02'), '"The saying means we ____ not judge the value of something just by its external appearance."', 'should', 'can', 'would', 'dare', 'A', '讲道理给建议"我们不应当只凭外表评判"——should。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.02'), '"It is getting late and Henry is tired, so he ____ to be on his way home now."', 'can', 'ought', 'will', 'would', 'B', '本分/恰当之事用 ought to;"他该上路了"——ought (to)。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.02'), '"You ____ not open the letter until two o''clock — that is the one strict rule."', 'can', 'would', 'must', 'dare', 'C', '强制性规定"两点前千万不可拆"——must not。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.02'), '"Visitors ____ show their passports at the consulate before entering; it is required by law."', 'should', 'would', 'could', 'have to', 'D', '"法律要求"是客观必须,用 have to;"必须出示护照"。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.02'), '"It''s already dark and the streets are unsafe, so you ____ better take a taxi home tonight."', 'had', 'would', 'could', 'should', 'A', '对当下情况的具体劝告"今晚最好打车"——had better。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.02'), '"If you find lost money, you ____ try your best to return it to its owner."', 'can', 'should', 'would', 'dare', 'B', '道义上的应当"应该尽力归还"——should。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.02'), '"To enter the upper-class party, every guest ____ wear formal evening clothes; no exceptions."', 'can', 'would', 'must', 'might', 'C', '"无一例外"表强制规定,"必须穿正装"——must。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.02'), '"There is no rush; you ____ to think it over carefully before settling in London."', 'can', 'will', 'dare', 'ought', 'D', '给建议"你应当好好考虑"——ought (to)。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.02'), '"The bank says customers ____ repay the loan within one year; it is a firm condition."', 'must', 'should', 'would', 'could', 'A', '"firm condition"是硬性规定,"必须一年内还清"——must。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.02'), '"Your coat is so worn; I think you ____ better buy a new one before the meeting."', 'would', 'had', 'can', 'ought', 'B', '针对眼前情况的劝告"最好先买件新的"——had better。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.02'), '"We ____ treat everyone we meet for the first time kindly, no matter how they look."', 'can', 'would', 'should', 'dare', 'C', '讲道理的建议"我们应当善待每个初识的人"——should。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.02'), '"Because he is on duty tonight, the guard ____ stay at the gate until midnight."', 'should', 'would', 'could', 'has to', 'D', '因值班这一客观职责而必须,"不得不待到午夜"——has to。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.02'), '"You don''t ____ to pay right now; you can settle the bill at the end of the month."', 'need', 'must', 'would', 'dare', 'A', '表"没有必要"用 need;"你不必现在付款"——needn''t (don''t need to)。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.02'), '"A play ____ to include all its key elements, or the audience will be confused."', 'can', 'ought', 'will', 'would', 'B', '说明应有之义"一部剧应当包含全部要素"——ought (to)。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.02'), '"Before the dress rehearsal, the actors ____ remember all their lines; that is the rule."', 'should', 'would', 'must', 'could', 'C', '"that is the rule"表硬性要求,"必须记住台词"——must。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.02'), '"You look pale and feverish; you ____ better see a doctor right away."', 'would', 'can', 'dare', 'had', 'D', '对当下身体状况的紧急劝告"最好马上看医生"——had better。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.02'), '"When we help someone in need, we ____ not always expect something in return."', 'should', 'can', 'would', 'dare', 'A', '道理上的应当"不该总想着回报"——should not。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.02'), '"All passengers ____ fasten their seat belts during take-off; the airline insists on it."', 'should', 'must', 'would', 'could', 'B', '航空公司硬性规定,"必须系好安全带"——must。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.02'), '"You ____ to save a little money each month so that you are ready for emergencies."', 'can', 'will', 'ought', 'dare', 'C', '理财建议"你应当每月存一点"——ought (to)。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.02'), '"The storm is coming fast; we ____ better head home before the rain starts."', 'would', 'can', 'ought', 'had', 'D', '对眼前情况的劝告"最好在下雨前回家"——had better。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.03'), '"Henry told the clerk that without small change he ____ not pay him until the end of the month."', 'would', 'can', 'must', 'dare', 'A', '转述"过去的将来":主句过去时,从句表将来用 would。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.03'), '"When she was young, my grandmother ____ sit by the window for hours, telling us old stories."', 'can', 'would', 'must', 'should', 'B', '表过去反复发生的习惯"过去常常一坐就是几小时"——would。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.03'), '"Excuse me, ____ you please step inside for a moment?" the brother asked the young man politely.', 'must', 'should', 'would', 'need', 'C', '客气的请求"您能进来一下吗"——would。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.03'), '"After years of practice, Henry ____ read the difficult contract without any help at all."', 'would', 'must', 'dare', 'could', 'D', '表过去具备的能力"能够读懂"——could。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.03'), '"The brothers promised that they ____ explain everything to Henry at exactly two o''clock."', 'would', 'can', 'must', 'ought', 'A', '转述过去的将来"会解释"——would。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.03'), '"____ you mind opening the window? It is rather warm in here," Portia said with a smile.', 'Must', 'Would', 'Should', 'Need', 'B', 'Would you mind…? 是客气请求的固定问法。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.03'), '"As a boy, Henry ____ spend whole afternoons sailing his little boat along the coast."', 'can', 'must', 'would', 'should', 'C', '表过去习惯"小时候常常"——would。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.03'), '"Henry was so weak from hunger that he ____ hardly walk another step."', 'would', 'must', 'dare', 'could', 'D', '表过去的能力(否定语境)"几乎走不动"——could hardly。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.03'), '"Jim isn''t here; he said earlier that he ____ be on duty at the library this afternoon."', 'would', 'can', 'must', 'ought', 'A', '转述过去说的将来安排"会值班"——would。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.03'), '"____ you do me a favour and pass the letter to Mr Adams?" the servant was asked.', 'Must', 'Could', 'Should', 'Need', 'B', '礼貌请求"能帮我个忙吗"——Could you…?。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.03'), '"In those days the old tailor ____ work late into the night, sewing by candlelight."', 'can', 'must', 'would', 'should', 'C', '表过去反复的习惯"那时常常工作到深夜"——would。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.03'), '"By the age of six, the boy ____ already write his own name in neat letters."', 'would', 'must', 'dare', 'could', 'D', '表过去已具备的能力"已经会写"——could。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.03'), '"The ambassador said that Miss Langham ____ be glad to keep Henry company at the party."', 'would', 'can', 'must', 'ought', 'A', '转述过去的将来"会很乐意"——would。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.03'), '"It is rather noisy here. ____ we move to a quieter corner to talk?" he asked kindly.', 'Must', 'Could', 'Should', 'Need', 'B', '客气建议性请求"我们能换个安静的角落吗"——Could we…?。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.03'), '"Whenever he had a free evening, Henry ____ wander through the old streets of London."', 'can', 'must', 'would', 'should', 'C', '表过去反复习惯"每当……他就常常"——would。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.03'), '"The room was so dark that Henry ____ not see the brothers'' faces clearly."', 'would', 'must', 'dare', 'could', 'D', '表过去的能力(否定)"看不清"——could not。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.03'), '"He assured the owner that he ____ come back for the other suits later that week."', 'would', 'can', 'must', 'ought', 'A', '转述过去的将来承诺"会回来取"——would。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.03'), '"____ you be so kind as to show Mr Adams out?" the brother said to the servant.', 'Must', 'Would', 'Should', 'Need', 'B', 'Would you be so kind as to…? 是极客气的请求。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.03'), '"Before he lost his money, Henry ____ swim across the bay every single morning."', 'can', 'must', 'would', 'should', 'C', '表过去反复的习惯"过去每天早上都游"——would。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U5' AND code='r3u5.03'), '"Henry felt sure that, with the letter in his pocket, his luck ____ soon change for the better."', 'can', 'must', 'dare', 'would', 'D', '转述过去时刻的将来感受"运气很快会好转"——would。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'A Bet on a Bank Note', 'Two rich brothers, Roderick and Oliver, had been arguing for days. Oliver believed that, with a single million-pound bank note, a man could live well in London for a whole month, even if he never actually spent it. His brother Roderick doubted this very much. To settle the argument, they decided to make a bet and find someone to test their idea. One day they saw a poor young man walking past their house. It was Henry Adams, an American who had been carried out to sea by a strong wind and brought to England by accident. He had no money and nowhere to stay. The brothers invited him in and gave him an envelope, telling him not to open it until two o''clock. Henry did not want their charity; he only wanted an honest job. Still, he took the letter and promised to wait. Inside lay the famous note that would change everything about how people treated him.', '记叙·两兄弟的打赌', 159, '[{"q":"Why did the two brothers decide to make a bet?","answer":"A","options":["To settle a long argument about what money could do.","To find a job for a poor American.","To sell their house in London.","To win money from each other''s bank."],"explanation":"原文 ''To settle the argument, they decided to make a bet'' 的转述。"},{"q":"How did Henry come to be in England?","answer":"B","options":["He sailed there on purpose to find work.","A storm carried him out to sea and a ship brought him over.","The brothers invited him from America.","He came to study at a London school."],"explanation":"原文 ''carried out to sea by a strong wind and brought to England by accident'' 的转述。"},{"q":"What was Henry''s attitude towards the brothers'' gift?","answer":"A","options":["He disliked charity and wanted an honest job instead.","He happily asked for more money.","He demanded a reward at once.","He refused to take the letter at all."],"explanation":"原文 ''did not want their charity; he only wanted an honest job'' 的转述。"}]'::jsonb, '[{"word":"bet","cn":"打赌"},{"word":"charity","cn":"施舍;慈善"},{"word":"envelope","cn":"信封"}]'::jsonb, 2, 'required3', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'The Suit That Changed Everything', 'Wearing a worn coat and holding the great bank note, Henry stepped into a tailor''s shop. At first the clerks treated him rudely, sending him downstairs to look at the cheapest ready-made suits. One clerk frowned and said the bright suit was all they had in his size. When Henry offered to pay later because he had no small change, the clerk clearly thought he was just a poor man making excuses. Then Henry handed over the note. The owner unfolded it slowly, hardly able to believe his eyes. Suddenly everything changed. The same people who had looked down on him now smiled, brought out their finest clothes, and said he could pay whenever he liked. They no longer cared that he had no address. The story shows how quickly people''s manners can change once they believe a stranger is rich. It quietly warns readers not to judge others by their clothes, and reminds us that respect should not depend on the size of a person''s wallet.', '记叙·裁缝店里的转变', 167, '[{"q":"How did the clerks treat Henry when he first entered?","answer":"B","options":["They welcomed him warmly and offered the best suits.","They treated him rudely and showed him only the cheapest clothes.","They gave him the suit for free.","They asked him to leave at once."],"explanation":"原文 ''treated him rudely, sending him downstairs to look at the cheapest'' 的转述。"},{"q":"What made the shop people suddenly change their manner?","answer":"C","options":["Henry gave them his home address.","Henry sang a song for them.","Henry showed them the huge bank note.","Henry told them about his boat."],"explanation":"原文 ''Then Henry handed over the note… Suddenly everything changed'' 的转述。"},{"q":"What lesson does the passage quietly teach?","answer":"D","options":["Always pay for clothes in cash.","Rich people deserve better service.","Tailors are usually dishonest.","How much money a person has should not decide our respect."],"explanation":"末段 ''respect should not depend on the size of a person''s wallet'' 的转述。"}]'::jsonb, '[{"word":"clerk","cn":"店员"},{"word":"frown","cn":"皱眉"},{"word":"manner","cn":"举止;态度"}]'::jsonb, 2, 'required3', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'The Honest Cleaner', 'Chen Liyan was a cleaner at a busy railway station. One morning she found a small bag holding ten thousand yuan that a traveller had dropped. Although she badly needed money herself, she did not hesitate. She handed the bag to the police so that its owner, Wang Zheng, could get it back. Wang was so moved that he offered her five thousand yuan as a reward, but Chen refused to take a single cent. Later, a neighbour told Wang that Chen had spent all her savings and taken out a large loan to pay for her sick daughter''s care. Wang felt he had to do something in return. He built a website to raise funds for the girl, and many kind strangers gave money. Chen''s story spread far and wide. It reminds us that being honest can bring help we never expect, and that a good deed often returns to the person who does it.', '记叙·拾金不昧的清洁工', 156, '[{"q":"What did Chen Liyan do after finding the bag of money?","answer":"A","options":["She gave it to the police to return to its owner.","She kept it for her daughter''s care.","She spent it on her own savings.","She left it at the station."],"explanation":"原文 ''handed the bag to the police so that its owner… could get it back'' 的转述。"},{"q":"Why did Wang Zheng build a fundraising website?","answer":"B","options":["Because he wanted to become famous online.","Because Chen had refused his reward and badly needed help.","Because the police told him to.","Because he had lost his own money again."],"explanation":"原文 ''felt he had to do something in return. He built a website to raise funds'' 的转述。"},{"q":"What is the main message of the story?","answer":"C","options":["Cleaners earn very little money.","Money should always be kept in a bank.","A good deed often brings unexpected help in return.","Railway stations are dangerous places."],"explanation":"末句 ''a good deed often returns to the person who does it'' 的转述。"}]'::jsonb, '[{"word":"hesitate","cn":"犹豫"},{"word":"loan","cn":"贷款"},{"word":"in return","cn":"作为回报"}]'::jsonb, 2, 'required3', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Pocket Money and Choices', 'For many teenagers, pocket money is the first real money they control. How they use it says a lot about the kind of adults they may become. Some spend every coin the moment they get it, buying snacks, games or small toys that are quickly forgotten. Others choose to save part of it each week, slowly watching their savings grow. A wise habit is to divide pocket money into three simple parts: one part to spend on small wishes, one part to save for something bigger, and one part to give to those in need. Learning to wait for what you want is not easy, but it teaches patience and self-control. Parents can help by letting children make their own choices, even if those choices sometimes lead to mistakes. After all, a mistake with a few coins today can prevent a far bigger mistake with real money in the future. In this way, pocket money becomes a small but valuable lesson in handling money wisely.', '说明·零花钱与选择', 165, '[{"q":"What does the way teenagers use pocket money suggest?","answer":"D","options":["How rich their parents are.","Which school they attend.","How many friends they have.","What sort of grown-ups they are likely to become."],"explanation":"原文 ''says a lot about the kind of adults they may become'' 的转述。"},{"q":"What ''three parts'' habit does the writer suggest?","answer":"A","options":["Spending, saving and giving to others in need.","Spending, lending and borrowing.","Buying, selling and hiding.","Eating, playing and sleeping."],"explanation":"原文 ''one part to spend… one part to save… one part to give'' 的转述。"},{"q":"Why does the writer say parents should allow small mistakes?","answer":"B","options":["Because mistakes make children spend more.","Because a small mistake now can prevent a bigger one later.","Because parents enjoy watching mistakes.","Because children never learn from being told."],"explanation":"原文 ''a mistake with a few coins today can prevent a far bigger mistake… in the future'' 的转述。"}]'::jsonb, '[{"word":"pocket money","cn":"零花钱"},{"word":"patience","cn":"耐心"},{"word":"divide","cn":"划分"}]'::jsonb, 2, 'required3', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'A Good Servant, a Bad Master', 'Long ago, the thinker Francis Bacon said that money is a good servant and a bad master. These few words hold a deep truth about how we should live with money. As a servant, money works for us. It buys food, books and medicine, pays for school, and lets us help the people we love. Used in this way, money brings comfort and opens doors. But money can also become a master. When people care only about getting more, they may lose their friends, their health and their honesty along the way. They work day and night, yet never feel they have enough. The danger is not money itself, but the place we give it in our hearts. A wise person keeps money in its proper place: useful, but never the most important thing. Happiness, kindness and time with family cannot be bought at any price. If we remember this, money will serve us well and never rule our lives.', '议论·金钱观', 160, '[{"q":"What does it mean that money is a ''good servant''?","answer":"C","options":["Money should be kept secret from others.","Money is the most important thing in life.","Money works for us and helps meet our real needs.","Money must always be saved, never spent."],"explanation":"原文 ''As a servant, money works for us. It buys food… lets us help'' 的转述。"},{"q":"What happens when money becomes a ''master''?","answer":"D","options":["People grow healthier and happier.","People stop using money at all.","People give all their money away.","People may lose friends, health and honesty chasing more."],"explanation":"原文 ''they may lose their friends, their health and their honesty'' 的转述。"},{"q":"According to the writer, where is the real danger?","answer":"A","options":["In the place we give money in our hearts.","In earning a high salary.","In saving money for the future.","In spending money on family."],"explanation":"原文 ''The danger is not money itself, but the place we give it in our hearts'' 的转述。"}]'::jsonb, '[{"word":"servant","cn":"仆人"},{"word":"master","cn":"主人"},{"word":"honesty","cn":"诚实"}]'::jsonb, 2, 'required3', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Saving for a Rainy Day', 'There is an old saying that we should save for a rainy day. It means that we ought to keep some money aside for hard times that we cannot see coming. Life is full of surprises. A person may suddenly fall ill, lose a job, or face a costly repair. Those who have saved a little each month can meet such troubles calmly, while those who have spent everything may have to take out a loan and worry for months. Saving does not require a large income; it requires a steady habit. Even putting away a small sum regularly will, over time, grow into a useful sum. The hardest part is starting, because spending always feels easier than saving. Yet the freedom that savings bring is worth the effort. With money set aside, you can make choices out of hope rather than fear. In short, a wise saver buys not just goods, but peace of mind for the days ahead.', '说明·储蓄的智慧', 160, '[{"q":"What does ''save for a rainy day'' really mean?","answer":"B","options":["Only buy umbrellas before it rains.","Keep some money for unexpected hard times.","Spend all your money quickly.","Borrow money from the bank often."],"explanation":"原文 ''keep some money aside for hard times that we cannot see coming'' 的转述。"},{"q":"According to the writer, what does saving mainly require?","answer":"C","options":["A very large income.","A new bank account each year.","A steady habit rather than a big income.","Help from rich friends."],"explanation":"原文 ''Saving does not require a large income; it requires a steady habit'' 的转述。"},{"q":"What ''peace of mind'' do savings bring, according to the text?","answer":"D","options":["The chance to spend more on snacks.","A way to avoid all work.","A reason to take out larger loans.","The freedom to make decisions led by hope, not fear."],"explanation":"原文 ''you can make choices out of hope rather than fear'' 的转述。"}]'::jsonb, '[{"word":"save","cn":"储蓄;存钱"},{"word":"income","cn":"收入"},{"word":"loan","cn":"贷款"}]'::jsonb, 2, 'required3', 'U5');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U5', 'Dinner with a Strange Note', 'Henry walked into a small restaurant, feeling very (1)____ because he had not eaten all day. A waiter showed him to a table, though the owner clearly thought such a poor-looking man could not (2)____ a proper meal. Henry ordered a large dinner and ate it slowly. When the bill came, he quietly handed over his huge bank (3)____. The waiter''s eyes grew wide, and he hurried to fetch the (4)____. "Could this really be the famous note from the (5)____?" the owner wondered aloud. At once their cold (6)____ changed into warm smiles. They said Henry could come back (7)____ he liked and order whatever he wished. To them, just having such a rich (8)____ in the room was a great honour. Henry was (9)____ at how quickly people''s behaviour could change. He realised that the same dinner had been served with a frown one minute and a smile the (10)____.', 152, 2, '[{"q":"1","answer":"A","options":["hungry","tired","angry","proud"],"explanation":"had not eaten all day → very hungry 很饿。"},{"q":"2","answer":"B","options":["sell","afford","cook","throw"],"explanation":"afford a meal 买得起一顿饭。"},{"q":"3","answer":"C","options":["card","book","note","ticket"],"explanation":"bank note 钞票。"},{"q":"4","answer":"D","options":["waiter","menu","key","owner"],"explanation":"去叫来 the owner 老板。"},{"q":"5","answer":"A","options":["papers","fields","shops","trees"],"explanation":"the famous note from the papers 报纸上的钞票。"},{"q":"6","answer":"B","options":["weather","manner","music","price"],"explanation":"cold manner 冷淡的态度。"},{"q":"7","answer":"C","options":["because","until","whenever","although"],"explanation":"come back whenever he liked 想来就来。"},{"q":"8","answer":"D","options":["enemy","child","animal","guest"],"explanation":"such a rich guest 这样一位富客。"},{"q":"9","answer":"A","options":["surprised","bored","asleep","absent"],"explanation":"be surprised at 对……感到惊讶。"},{"q":"10","answer":"B","options":["year","next","week","month"],"explanation":"with a smile the next (minute) 下一分钟就笑脸相迎。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U5', 'What to Do If You Lose Your Money Abroad', 'Imagine you are travelling in a foreign country when you suddenly find that your money is (1)____. This situation is frightening, but you should try to stay (2)____. First, go to your nearest (3)____, where the staff can help you to some (4)____. They may not give you cash, but they can offer useful advice. Second, you (5)____ to check with local charities, which sometimes (6)____ help to travellers in need. Whatever you do, you must not let fear (7)____ you to do something foolish. Some people might (8)____ that stealing food would solve the problem, but getting caught could ruin your whole (9)____. Most importantly, always keep a little cash hidden in a safe place (10)____ such an emergency happens. A calm traveller who plans ahead will get through almost any trouble.', 133, 2, '[{"q":"1","answer":"C","options":["ready","free","gone","new"],"explanation":"your money is gone 钱不见了。"},{"q":"2","answer":"D","options":["rich","loud","busy","calm"],"explanation":"stay calm 保持冷静。"},{"q":"3","answer":"A","options":["consulate","garden","market","stadium"],"explanation":"go to the consulate 去领事馆。"},{"q":"4","answer":"B","options":["price","extent","noise","song"],"explanation":"to some extent 在一定程度上。"},{"q":"5","answer":"C","options":["must","need","ought","dare"],"explanation":"you ought to check 你应当核实。"},{"q":"6","answer":"D","options":["sell","lose","break","offer"],"explanation":"offer help 提供帮助。"},{"q":"7","answer":"A","options":["cause","thank","teach","feed"],"explanation":"let fear cause you 让恐惧使你……。"},{"q":"8","answer":"B","options":["forget","think","refuse","promise"],"explanation":"might think that 也许会以为。"},{"q":"9","answer":"C","options":["shop","boat","life","coat"],"explanation":"ruin your whole life 毁掉你的一生。"},{"q":"10","answer":"D","options":["unless","so that","even if","in case"],"explanation":"in case such an emergency happens 以防发生这种紧急情况。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U5', 'My First Time Managing Money', 'When I turned twelve, my parents began to give me a small amount of pocket money every (1)____. At first I spent it all at once on snacks and toys, and by the next day my pockets were (2)____ again. My mother gently told me that money was a good (3)____ but a bad master, and that I (4)____ learn to control it. So I made a simple (5)____: I divided my money into three parts. One part I could (6)____ on small treats, one part I would (7)____ for something bigger, and one part I gave to children in (8)____. It was not easy to wait, and it taught me real (9)____. A few months later, I had saved enough to buy the bicycle I had always wanted. That day I felt proud, because I had earned it through my own (10)____.', 143, 2, '[{"q":"1","answer":"A","options":["week","year","century","second"],"explanation":"every week 每周。"},{"q":"2","answer":"B","options":["full","empty","heavy","wet"],"explanation":"pockets were empty again 口袋又空了。"},{"q":"3","answer":"C","options":["price","noise","servant","garden"],"explanation":"a good servant 好仆人(呼应名言)。"},{"q":"4","answer":"D","options":["dare not","used to","would rather","ought to"],"explanation":"ought to learn 应当学会。"},{"q":"5","answer":"A","options":["plan","mistake","noise","joke"],"explanation":"made a simple plan 做了个简单的计划。"},{"q":"6","answer":"B","options":["lose","spend","sell","hide"],"explanation":"spend on small treats 花在小零食上。"},{"q":"7","answer":"C","options":["throw","break","save","drop"],"explanation":"save for something bigger 为更大的东西攒钱。"},{"q":"8","answer":"D","options":["games","songs","shops","need"],"explanation":"children in need 有需要的孩子。"},{"q":"9","answer":"A","options":["patience","fear","anger","luck"],"explanation":"taught me real patience 教会我真正的耐心。"},{"q":"10","answer":"B","options":["mistake","effort","weather","noise"],"explanation":"through my own effort 靠自己的努力。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U5', 'The School Charity Sale', 'Last month our class held a charity (1)____ to raise money for a sick classmate. Everyone brought old books, toys and clothes that were still in good (2)____. We set up tables in the playground and put a clear (3)____ on each item. At first I was nervous and (4)____ to call out to passers-by, but soon I grew braver. Many parents were (5)____ to pay a little more than we asked, just to support a good (6)____. By the end of the day, we had raised far more money than we had ever (7)____. None of us kept a single cent for (8)____; every coin went to help our classmate''s family. The best part was not the money itself, but the warm feeling of doing something (9)____ together. I learned that even a small (10)____ of kindness can make a real difference to someone in trouble.', 147, 2, '[{"q":"1","answer":"C","options":["test","race","sale","trip"],"explanation":"a charity sale 慈善义卖。"},{"q":"2","answer":"D","options":["price","manner","weather","condition"],"explanation":"in good condition 状况良好。"},{"q":"3","answer":"A","options":["price","song","noise","joke"],"explanation":"put a clear price 标个清楚的价格。"},{"q":"4","answer":"B","options":["promised","hesitated","refused","managed"],"explanation":"hesitated to call out 迟疑着不敢叫卖。"},{"q":"5","answer":"C","options":["afraid","sorry","willing","tired"],"explanation":"were willing to pay 愿意多付。"},{"q":"6","answer":"D","options":["price","noise","shop","cause"],"explanation":"support a good cause 支持公益事业。"},{"q":"7","answer":"A","options":["hoped","lost","sold","thrown"],"explanation":"more than we had hoped 比我们期望的还多。"},{"q":"8","answer":"B","options":["himself","ourselves","themselves","herself"],"explanation":"kept… for ourselves 给自己留。"},{"q":"9","answer":"C","options":["wrong","useless","good","empty"],"explanation":"doing something good 做好事。"},{"q":"10","answer":"D","options":["price","noise","shop","act"],"explanation":"a small act of kindness 一个小小的善举。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U5', 'Smart Ways to Save Money', 'Saving money is a skill that anyone can (1)____ with a little practice. The first step is to know exactly where your money (2)____ each week. Many people are surprised to find how much they waste on things they do not really (3)____. A useful habit is to wait a day before buying anything that is not (4)____; often the wish to buy it simply goes away. You should also try to (5)____ a small sum regularly, even if it is only a few coins. Over time, these coins (6)____ into a useful amount. When you shop, compare (7)____ before you decide, and never let a clever advertisement (8)____ you into buying what you do not need. Saving does not mean you can never (9)____ yourself; it means spending on what truly matters. Step by step, these simple habits will give you greater (10)____ over your own money.', 148, 2, '[{"q":"1","answer":"A","options":["learn","lose","sell","drop"],"explanation":"a skill anyone can learn 人人都能学会。"},{"q":"2","answer":"B","options":["sleeps","goes","sings","drives"],"explanation":"where your money goes 钱花到哪去了。"},{"q":"3","answer":"C","options":["hide","throw","need","break"],"explanation":"do not really need 并不真的需要。"},{"q":"4","answer":"D","options":["empty","wrong","loud","necessary"],"explanation":"not necessary 并非必需。"},{"q":"5","answer":"A","options":["save","waste","lose","spend"],"explanation":"save a small sum 存一小笔。"},{"q":"6","answer":"B","options":["break","grow","fall","stop"],"explanation":"these coins grow into 这些硬币会增长为。"},{"q":"7","answer":"C","options":["songs","noises","prices","games"],"explanation":"compare prices 比较价格。"},{"q":"8","answer":"D","options":["thank","teach","feed","fool"],"explanation":"let an advertisement fool you 让广告骗了你。"},{"q":"9","answer":"A","options":["enjoy","lose","sell","hide"],"explanation":"enjoy yourself 享受生活。"},{"q":"10","answer":"B","options":["noise","control","price","weather"],"explanation":"greater control over your money 对钱更有掌控力。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U5', 'Learning to Be Thankful', 'My grandfather grew up very (1)____, and his family often had little to eat. Yet whenever he tells me about those days, he never (2)____. Instead, he says that being poor taught him to value every small (3)____ in life. He learned to fix his own shoes, to share what he had, and to be (4)____ for even a warm meal. "Money," he often says, "can buy many things, but it cannot buy a happy (5)____." Today our family is more comfortable, but he still hates to (6)____ anything. He keeps a little notebook in which he writes down the things he is thankful (7)____ each day. At first I thought this was a strange (8)____, but slowly I began to understand. Counting your blessings, he says, makes you feel (9)____ no matter how much you own. Because of him, I have learned that true wealth is not about how much you have, but how (10)____ you feel for what you have.', 162, 2, '[{"q":"1","answer":"C","options":["rich","tall","poor","busy"],"explanation":"grew up very poor 家境贫寒。"},{"q":"2","answer":"D","options":["smiles","sleeps","sings","complains"],"explanation":"never complains 从不抱怨。"},{"q":"3","answer":"A","options":["gift","price","noise","shop"],"explanation":"every small gift in life 生活中每件小小的恩赐。"},{"q":"4","answer":"B","options":["angry","thankful","sorry","afraid"],"explanation":"be thankful for 心怀感激。"},{"q":"5","answer":"C","options":["shop","boat","heart","coat"],"explanation":"a happy heart 一颗快乐的心。"},{"q":"6","answer":"D","options":["save","keep","share","waste"],"explanation":"hates to waste anything 讨厌浪费。"},{"q":"7","answer":"A","options":["for","at","to","by"],"explanation":"thankful for 对……感激。"},{"q":"8","answer":"B","options":["price","habit","noise","shop"],"explanation":"a strange habit 一个奇怪的习惯。"},{"q":"9","answer":"C","options":["poor","angry","rich","tired"],"explanation":"makes you feel rich 让你感到富有。"},{"q":"10","answer":"D","options":["sorry","afraid","bored","thankful"],"explanation":"how thankful you feel 你有多感恩。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U5 听力·对话 Lending a Friend Money', '必修三 U5 · dialogue', 3, 'Tom: Anna, could you lend me twenty pounds until next week?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U5 听力·短文 A Good Servant, a Bad Master', '必修三 U5 · passage', 2, 'A famous thinker once said that money is a good servant but a bad master. As a servant, money does useful work for us. It pays for food, books and medicine, and lets us help the people we love. But when people care only about getting more and more, money becomes a master that rules their lives. The real danger is not money itself, but the place we give it in our hearts. A wise person keeps money useful, but never lets it become the most important thing of all.', '一位著名思想家说过,金钱是好仆人却是坏主人。作为仆人,金钱为我们做有用的事——付食物、书籍、药品的钱,让我们帮助所爱的人;但当人们只在乎不断索取更多时,金钱就成了主宰生活的主人。真正的危险不在金钱本身,而在于我们把它放在心中的位置;明智的人让金钱有用,却绝不让它成为最重要的东西。', 'uk_female', '[{"q":"What did the famous thinker say about money?","type":"choice","answer":"D","options":["It is the most important thing in life.","It can buy happiness.","It should never be used.","It is a good servant but a bad master."]},{"q":"What does money do as a ''servant''?","type":"choice","answer":"A","options":["It does useful work, like paying for food and medicine.","It rules people''s lives.","It makes people lose their friends.","It hides in the bank."]},{"q":"When does money become a ''master''?","type":"choice","answer":"B","options":["When people save a little each month.","When people care only about getting more and more.","When people give it away.","When people spend it on family."]},{"q":"Where is the real danger, according to the passage?","type":"choice","answer":"C","options":["In earning a salary.","In buying medicine.","In the place we give money in our hearts.","In helping the people we love."]},{"q":"What does a wise person do with money?","type":"choice","answer":"D","options":["Makes it the centre of life.","Refuses to use it at all.","Spends it as fast as possible.","Keeps it useful but never the most important thing."]}]'::jsonb, '[]'::jsonb, 'short', 'required3', 'U5');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U5 听力·对话 Opening a Savings Account', '必修三 U5 · dialogue', 3, 'Clerk: Good morning. How can I help you today?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U5 听力·短文 Giving to Charity', '必修三 U5 · passage', 2, 'Many people choose to give part of their money to charity. They do not expect anything in return; they simply want to help those in need. Even a small gift can make a real difference. Some donate to help sick children, others to build schools or feed the hungry. Giving teaches us that money is not only for ourselves. In fact, people who share often feel happier than those who keep everything. As an old saying goes, kindness is the one gift that grows when you give it away.', '许多人选择把一部分钱捐给慈善机构。他们不求任何回报,只想帮助有需要的人;哪怕一份小小的捐赠也能带来真正的改变。有人捐助患病的孩子,有人捐建学校或救济饥民。给予让我们懂得,钱不只是为了自己;事实上,乐于分享的人往往比独享一切的人更快乐。正如一句老话所说,善良是唯一一种越给越多的礼物。', 'uk_female', '[{"q":"Why do people give money to charity?","type":"choice","answer":"B","options":["They expect a large reward.","They simply want to help those in need.","They are forced to by the bank.","They want to become famous."]},{"q":"What can even a small gift do?","type":"choice","answer":"C","options":["Ruin a person''s life.","Cost nothing at all.","Make a real difference.","Cause a lot of trouble."]},{"q":"What does giving teach us, according to the passage?","type":"choice","answer":"D","options":["Money should be kept secret.","Charity is a waste of money.","Only rich people can give.","Money is not only for ourselves."]},{"q":"How do people who share often feel?","type":"choice","answer":"A","options":["Happier than those who keep everything.","Angrier than before.","Poorer and sadder.","Bored with their lives."]},{"q":"What does the old saying compare kindness to?","type":"choice","answer":"B","options":["A coin that is quickly lost.","A gift that grows when you give it away.","A bill that must be paid.","A note printed on paper."]}]'::jsonb, '[]'::jsonb, 'short', 'required3', 'U5');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U5 听力·对话 Planning the Weekend Spending', '必修三 U5 · dialogue', 3, 'Ben: We''ve got twenty pounds for the weekend. How should we spend it?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U5 听力·短文 A Tip for Spending Wisely', '必修三 U5 · passage', 2, 'Here is a simple tip for anyone who wants to spend money wisely. Before you buy something, wait one whole day and ask yourself if you really need it. Very often, the strong wish to buy it will quietly go away. This little habit can save you a surprising amount of money over a year. Remember, every coin you do not waste today is a coin you can use for something important tomorrow. Spending wisely is not about being mean; it is about giving your money to the things that truly matter.', '给想理性花钱的人一个小贴士:买东西前先等一整天,问问自己是否真的需要它;很多时候,那股强烈的购买欲会悄悄消退。这个小习惯一年下来能省下出人意料的一笔钱。记住,你今天没浪费的每一枚硬币,都是明天可用于重要之事的硬币。理性消费不是吝啬,而是把钱花在真正要紧的事情上。', 'uk_female', '[{"q":"What should you do before buying something?","type":"choice","answer":"D","options":["Buy two of it at once.","Borrow money to buy it.","Throw away the old one.","Wait one whole day and ask if you really need it."]},{"q":"What often happens after you wait?","type":"choice","answer":"A","options":["The strong wish to buy it goes away.","The price goes up.","You forget your own name.","The shop closes forever."]},{"q":"What can this little habit do over a year?","type":"choice","answer":"B","options":["Cost you a lot of money.","Save you a surprising amount of money.","Make you spend more.","Ruin your savings."]},{"q":"What is every coin you do not waste today?","type":"choice","answer":"C","options":["A coin you must give away.","A coin that is now worthless.","A coin you can use for something important tomorrow.","A coin you should hide forever."]},{"q":"What is spending wisely really about, according to the passage?","type":"choice","answer":"D","options":["Being mean to everyone.","Never buying anything at all.","Showing off how rich you are.","Giving your money to things that truly matter."]}]'::jsonb, '[]'::jsonb, 'short', 'required3', 'U5');
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (10, 'A Sensible Attitude to Money(理性的金钱观:如何管理零花钱)', 'How to Manage Your Pocket Money Wisely', '假设你叫李华,校刊正在征集关于「如何聪明地管理零花钱」的稿件。请用英语写一篇约100词的短文,内容包括:① 用一句话表明你对金钱的看法(金钱是好仆人,不应成为主人);② 给出两三条管理零花钱的具体建议(如分配/储蓄/捐赠);③ 总结理性用钱的意义。注意:观点鲜明、条理清楚、恰当使用情态动词(should/ought to/must 等)。', 'Suppose you are Li Hua. Your school magazine is collecting articles on "How to manage your pocket money wisely". Write a short passage (about 100 words) including: 1) one sentence stating your view of money (money is a good servant, not a master); 2) two or three pieces of practical advice on managing pocket money (e.g. dividing it, saving, giving to charity); 3) a short conclusion on why a sensible attitude to money matters. Use modal verbs (should / ought to / must) properly.', '["亮明观点(Money is a good servant but a bad master, so we should …)","建议1 分配/储蓄(We ought to divide our pocket money and save part of it)","建议2 慈善/不乱花(We should give a little to those in need and must not waste it)","总结意义(A sensible attitude to money helps us …)恰当用情态动词"]'::jsonb, 70, 100, 'As an old saying goes, money is a good servant but a bad master. I believe that we should control our money, and never let it control us. So how can teenagers manage their pocket money wisely? First, we ought to divide it into three parts: one to spend on real needs, one to save for the future, and one to give to those in need. Second, we must not waste money on things we do not really want. We had better wait a day before buying anything new. A sensible attitude to money helps us learn patience and care for others, and it will serve us well for the rest of our lives.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["As an old saying goes, money is a good servant but a bad master.","We ought to divide it into three parts: one to spend, one to save, and one to give.","We must not waste money on things we do not really want.","A sensible attitude to money helps us learn patience and care for others."]'::jsonb, '[{"wrong":"We should to save part of it.","correct":"We should save part of it.","note":"情态动词 should 后直接跟动词原形,不加 to。"},{"wrong":"We must not to waste money.","correct":"We must not waste money.","note":"must not 后接动词原形,不加 to。"},{"wrong":"Money are a good servant.","correct":"Money is a good servant.","note":"money 是不可数名词,谓语用单数 is。"}]'::jsonb, '【理财议论/建议结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (10, 'required3', 'U5', '{"title":"情态动词 + would 表过去将来 速查","intro":"情态动词后接动词原形,本身不随人称变化。三大功能要分清:① 推测可能性(must/can''t/may/might/could);② 义务建议必要(should/ought to/must/have to/had better/need);③ 能力请求意愿 + would 表过去将来/过去习惯。推测强弱看证据。","table":{"headers":["情态动词","功能 / 用法 / 例句"],"rows":[["must","强肯定推测「一定」(证据充分):He must be rich. ｜ 强义务「必须」:You must wear formal clothes."],["can''t","否定推测「不可能」:It can''t be true.(注意:推测的否定不用 mustn''t)"],["may / might / could","弱推测「也许、可能」(证据不足):He may be at the consulate."],["should / ought to","建议、应当(语气较弱):You should save part of it. / You ought to go now."],["had better","针对当下的具体劝告「最好」:You''d better see a doctor. (否定 had better not)"],["can / could","能力「能」:He could read it. ｜ 客气请求:Could you help me?"],["will / would","意愿;would 更客气;would 转述「过去将来」:He said he would help. ｜ would 表过去习惯:She would sit for hours."]]},"specialRules":[{"rule":"推测的否定用 can''t(不可能),不是 mustn''t(mustn''t = 禁止)","mark":"It can''t be him. √ / It mustn''t be him. ×（推测）"},{"rule":"must(必须)的否定是 needn''t / don''t have to(不必),mustn''t 是「禁止」","mark":"You needn''t pay now（不必）≠ You mustn''t（禁止)"},{"rule":"would 转述过去的将来:主句过去时,从句的将来用 would","mark":"He said he would come.（= will → would)"},{"rule":"would / used to 表过去习惯;但 would 只接动作,不接状态","mark":"She would sit for hours.√ / She would be tall.×（状态用 used to)"},{"rule":"情态动词后一律跟动词原形,不加 to(ought to / had better 除外的固定形式)","mark":"should go √ / should to go ×"}],"why":["情态动词表达的是说话人的「态度」——有多大把握(推测)、有多强的要求(义务)、有没有能力或意愿。把握越大用 must,把握越小用 may/might;要求越硬用 must,越软用 should。would 则把现在的 will「往过去推一格」,用来转述过去说的将来。"],"gaokaoPoints":["推测三档:must（强）/ may·might·could（弱）/ can''t（否定),语境给的证据决定选哪一个,语法填空与单选高频。","must not(禁止)vs needn''t / don''t have to(不必)的区别是常考陷阱。","would 表「过去的将来」与「过去反复习惯」,在记叙文和转述句中频繁出现。"],"examVsReal":[{"exam":"He must be very tired.（考试:强推测）","real":"He''s gotta be exhausted.","note":"考试用 must 作推测;口语里 ''ve got to / gotta 也常表「一定是」"},{"exam":"You ought to save some money.（考试:建议）","real":"You really should put a bit aside.","note":"ought to 与 should 意思相近,口语里 should 更常用,ought to 偏正式"},{"exam":"She would sit there for hours.（考试:过去习惯）","real":"She used to sit there for ages.","note":"would 和 used to 都表过去习惯;用 would 须有时间背景,used to 可单独使用"}]}'::jsonb);
